99	// pushURLsByRemote parses `git remote -v` into remote name -> push URLs in git's
100	// own order.
101	func pushURLsByRemote(ctx context.Context, dir string) (map[string][]string, error) {
102		out, err := gitRunner(ctx, dir, "remote", "-v")
103		if err != nil {
104			return nil, fmt.Errorf("list git remotes: %w", err)
105		}
106		urls := make(map[string][]string)
107		for _, line := range strings.Split(out, "\n") {
108			// "<name>\t<url> (push)" — fetch lines are the same shape and ignored.
109			name, rest, found := strings.Cut(strings.TrimSpace(line), "\t")
110			if !found || !strings.HasSuffix(rest, "(push)") {
111				continue
112			}
113			url := strings.TrimSpace(strings.TrimSuffix(rest, "(push)"))
114			if url != "" {
115				urls[name] = append(urls[name], url)
116			}
117		}
118		// An empty map is a legitimate answer (a repo with no remotes), so it is
119		// returned as such rather than as an error the caller would have to classify.
120		return urls, nil
121	}
