123	// ambiguous reports whether anything is worth telling the user: a remote whose
124	// checkpoints face several push URLs, or several remotes to choose between.
125	func (t remoteTopology) ambiguous() bool {
126		unpinned := 0
127		for _, d := range t.destinations {
128			if d.fansOut() {
129				return true
130			}
131			if !d.pinned {
132				unpinned++
133			}
134		}
135		return unpinned > 1
136	}
