138	// describeCheckpointDestination writes an explanation of where checkpoints go,
139	// under the given header. Writes nothing when the destination is unambiguous.
140	func (t remoteTopology) describeCheckpointDestination(w io.Writer, header string) {
141		if !t.ambiguous() {
142			return
143		}
144	
145		fmt.Fprintln(w, header)
146	
147		for _, d := range t.destinations {
148			if !d.fansOut() {
149				continue
150			}
151			fmt.Fprintf(w, "  Remote %q pushes to %d URLs:\n", d.name, len(d.pushURLs))
152			for i, u := range d.pushURLs {
153				marker := "  "
154				if i == 0 && t.primaryIsRefs {
155					marker = "→ "
156				}
157				fmt.Fprintf(w, "    %s%s\n", marker, gitremote.RedactURLOrPath(u))
158			}
159			if t.primaryIsRefs {
160				fmt.Fprintln(w, "    Checkpoints go to the first URL only; the others receive your code but")
161				fmt.Fprintln(w, "    no session history. Clone that first repository to resume elsewhere.")
162			} else {
163				fmt.Fprintln(w, "    Checkpoints are pushed to every URL. If one rejects them or is")
164				fmt.Fprintln(w, "    unreachable it is reported and left behind, and only the fetch URL is")
165				fmt.Fprintln(w, "    ever reconciled — so those URLs can fall permanently out of date.")
166			}
167		}
168	
169		if names := t.unpinnedNames(); len(names) > 1 {
170			fmt.Fprintf(w, "  This repo has %d remotes (%s).\n", len(names), strings.Join(names, ", "))
171			fmt.Fprintln(w, "    Checkpoints sync to a single elected remote — not to whichever one you")
172			fmt.Fprintln(w, "    push to. A push to any other remote carries your code but no session")
173			fmt.Fprintln(w, "    history. Run `entire status` to see the elected destination and how many")
174			fmt.Fprintln(w, "    checkpoints are waiting for it.")
175		}
176	
177		fmt.Fprintln(w, "  To pin one repository for checkpoints, set checkpoint_remote in")
178		fmt.Fprintln(w, "  .entire/settings.json (or .entire/settings.local.json to keep it to this clone).")
179	}
