181	// unpinnedNames lists the remotes whose checkpoint destination is not already
182	// pinned by a checkpoint_remote.
183	func (t remoteTopology) unpinnedNames() []string {
184		var names []string
185		for _, d := range t.destinations {
186			if !d.pinned {
187				names = append(names, d.name)
188			}
189		}
190		return names
191	}
