193	// printCheckpointDestinationNote explains where checkpoints go when this repo's
194	// remotes make that a choice. Shared by `entire enable` — the moment a user is
195	// most likely to be looking, and the least surprising place to learn it — and by
196	// `entire doctor`, which reports it on demand. Silent on the ordinary repo, so it
197	// adds nothing to the common output.
198	func printCheckpointDestinationNote(ctx context.Context, w io.Writer, header string) {
199		inspectRemoteTopology(ctx).describeCheckpointDestination(w, header)
200	}
