1855	// CheckpointRemoteIsLocalOnly reports whether a checkpoint_remote entry is
1856	// present in .entire/settings.local.json.
1857	//
1858	// That file is gitignored and per-clone, so a checkpoint_remote living there
1859	// is this developer's own explicit choice. Callers use this to distinguish
1860	// "I configured where my checkpoints go" from "I inherited a committed setting
1861	// that points at the upstream project's checkpoint repo".
1862	//
1863	// The filename alone does not establish that — see localLayerTrackedReason.
1864	// This reads the file directly rather than through Load, so it repeats the
1865	// tracked check the loader applies to the local layer —
1866	// without it, the ownership signal this gates could be inherited from the very
1867	// upstream it is meant to distinguish.
1868	//
1869	// Best-effort: an unreadable, malformed, or unverifiable local file reports
1870	// false, which is the conservative answer (callers then fall back to weaker
1871	// ownership signals).
1872	func CheckpointRemoteIsLocalOnly(ctx context.Context) bool {
1873		path, raw, exists, err := LoadLocalRaw(ctx)
1874		if err != nil || !exists {
1875			return false
1876		}
1877		if classifyLocalSettings(ctx, path) != localOwn {
1878			return false
1879		}
1880		return rawHasKey(raw, "strategy_options", "checkpoint_remote")
1881	}
