1883	// GetCheckpointRemote returns the configured checkpoint remote.
1884	// Expects a structured object: {"provider": "github", "repo": "org/repo"}.
1885	// Returns nil if not configured, wrong type, or missing required fields.
1886	func (s *EntireSettings) GetCheckpointRemote() *CheckpointRemoteConfig {
1887		if s.StrategyOptions == nil {
1888			return nil
1889		}
1890		val, ok := s.StrategyOptions["checkpoint_remote"]
1891		if !ok {
1892			return nil
1893		}
1894		m, ok := val.(map[string]any)
1895		if !ok {
1896			return nil
1897		}
1898		provider, providerOK := m["provider"].(string)
1899		repo, repoOK := m["repo"].(string)
1900		if !providerOK || !repoOK || provider == "" || repo == "" {
1901			return nil
1902		}
1903		if !strings.Contains(repo, "/") {
1904			return nil
1905		}
1906		return &CheckpointRemoteConfig{Provider: provider, Repo: repo}
1907	}
