// legacyCheckpointRemote names the remote the election would have picked
// without the Entire tier: origin, else the sole non-Entire remote, else the
// first non-Entire remote in config order. Empty when every remote is an
// Entire remote. Local-only (one `git remote -v`).
func legacyCheckpointRemote(ctx context.Context) string {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return ""
	}
	byRemote, err := pushURLsByRemote(ctx, root)
	if err != nil {
		return ""
	}
	entire := make(map[string]bool)
	for _, name := range strategy.EntireRemotes(ctx) {
		entire[name] = true
	}
	names := make([]string, 0, len(byRemote))
	for name := range byRemote {
		if !entire[name] {
			names = append(names, name)
		}
	}
	sort.Strings(names)
	switch {
	case len(names) == 0:
		return ""
	case slices.Contains(names, "origin"):
		return "origin"
	default:
		return names[0]
	}
}

// localCheckpointsExist reports whether this clone holds any checkpoint
// artifact — a per-checkpoint ref or the v1 branch — on either backend. One
// `git for-each-ref`, no network.
func localCheckpointsExist(ctx context.Context) bool {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return false
	}
	out, err := gitRunner(ctx, root, "for-each-ref", "--count=1",
		checkpoint.CheckpointRefPrefix, "refs/heads/"+paths.MetadataBranchName)
	if err != nil {
		return false
	}
	return strings.TrimSpace(out) != ""
}
